#!/usr/bin/env bash
# The showcase scripts (examples/showcase/) under protoclj and Babashka, side
# by side: wall time and peak RSS from /usr/bin/time -v, RUNS interleaved
# rounds (the runtime order alternates each round), medians, and a check
# that both runtimes print the same output for every script on every run.
#
# Usage:
#   run.sh PROTOCLJ BB [DATA_DIR] [OUT_DIR]
#
#   PROTOCLJ  the protoclj binary (build it from a clean worktree)
#   BB        the bb binary (a static release from github.com/babashka/babashka)
#   DATA_DIR  where the inputs are, generated by examples/showcase/gen-data.py
#             when missing (default: ./data, about 190 MB)
#   OUT_DIR   where the raw results go (default: ./out)
#
# Environment: RUNS (default 5); QUIET_GATE, a command that waits until the
# machine is quiet before each round (default: none; the 2026-10-24 run used
# protoCore's quiet.py with QUIET_CORES=4.0). The load average before each
# round is recorded either way.
set -u
PROTOCLJ=${1:?usage: run.sh PROTOCLJ BB [DATA_DIR] [OUT_DIR]}
BB=${2:?usage: run.sh PROTOCLJ BB [DATA_DIR] [OUT_DIR]}
HERE=$(cd "$(dirname "$0")" && pwd)
SHOW=$(cd "$HERE/../../../examples/showcase" && pwd)
DATA=${3:-$HERE/data}
OUT=${4:-$HERE/out}
RUNS=${RUNS:-5}
mkdir -p "$OUT"
if [[ ! -f "$DATA/access.log" || ! -f "$DATA/orders.json" || ! -f "$DATA/corpus.txt" ]]; then
    python3 -I "$SHOW/gen-data.py" "$DATA"
fi

{
    echo "date: $(date -u +%FT%TZ)"
    echo "host: $(uname -srm), $(nproc) cpus"
    echo "protoclj: $PROTOCLJ ($("$PROTOCLJ" --version 2>&1 | head -1))"
    ldd "$PROTOCLJ" 2>/dev/null | grep -i protocore | sed 's/^/  /'
    echo "bb: $BB ($("$BB" --version 2>&1 | head -1))"
    for f in access.log orders.json corpus.txt; do
        echo "input $f: $(wc -c < "$DATA/$f") bytes, sha256 $(sha256sum "$DATA/$f" | cut -c1-16)"
    done
} > "$OUT/environment.txt"

# name | script | stdin file ("-" for none) | argument
WORKLOADS=(
    "startup|empty.clj|-|"
    "factorial|factorial.clj|-|"
    "grep|grep.clj|$DATA/access.log|"
    "json|json-transform.clj|-|$DATA/orders.json"
    "wordfreq|word-freq.clj|$DATA/corpus.txt|"
)

measure() {  # runtime-label binary name script stdin arg round
    local label=$1 bin=$2 name=$3 script=$4 in=$5 arg=$6 round=$7
    local tag="$OUT/${name}_${label}_r${round}"
    local -a cmd=("$bin" "$SHOW/$script")
    [[ -n "$arg" ]] && cmd+=("$arg")
    if [[ "$in" == "-" ]]; then
        /usr/bin/time -v -o "$tag.time" "${cmd[@]}" < /dev/null > "$tag.out" 2> "$tag.err"
    else
        /usr/bin/time -v -o "$tag.time" "${cmd[@]}" < "$in" > "$tag.out" 2> "$tag.err"
    fi
    echo $? > "$tag.rc"
}

for ((r = 1; r <= RUNS; ++r)); do
    if [[ -n "${QUIET_GATE:-}" ]]; then $QUIET_GATE > "$OUT/quiet_r$r.txt" 2>&1; fi
    echo "round $r $(date -u +%T) load $(cut -d' ' -f1-3 /proc/loadavg)" >> "$OUT/rounds.txt"
    for w in "${WORKLOADS[@]}"; do
        IFS='|' read -r name script in arg <<<"$w"
        if (( r % 2 == 1 )); then order="protoclj bb"; else order="bb protoclj"; fi
        for label in $order; do
            bin=$PROTOCLJ; [[ $label == bb ]] && bin=$BB
            measure "$label" "$bin" "$name" "$script" "$in" "$arg" "$r"
        done
    done
done

# Start-up at a finer grain than /usr/bin/time's 10 ms: perf stat over 50
# runs of the empty script, three interleaved passes (when perf is there).
if command -v perf > /dev/null; then
    for pass in 1 2 3; do
        for label in protoclj bb; do
            bin=$PROTOCLJ; [[ $label == bb ]] && bin=$BB
            perf stat -r 50 -x, -e task-clock "$bin" "$SHOW/empty.clj" 2>> "$OUT/startup_perf_$label.txt" > /dev/null
        done
    done
fi

python3 -I - "$OUT" "$RUNS" <<'PY' | tee "$OUT/summary.txt"
import pathlib, re, statistics, sys
out, runs = pathlib.Path(sys.argv[1]), int(sys.argv[2])
names = ["startup", "factorial", "grep", "json", "wordfreq"]
def parse(p):
    t = p.read_text()
    m = re.search(r"Elapsed \(wall clock\) time \(h:mm:ss or m:ss\): (?:(\d+):)?(\d+):([\d.]+)", t)
    h, mnt, sec = int(m.group(1) or 0), int(m.group(2)), float(m.group(3))
    rss = int(re.search(r"Maximum resident set size \(kbytes\): (\d+)", t).group(1))
    return (h * 3600 + mnt * 60 + sec, rss)
ok = True
print(f"{'workload':10} {'protoclj s':>11} {'bb s':>8} {'ratio':>6} {'protoclj MB':>12} {'bb MB':>7}  output")
for n in names:
    res, outs = {}, {}
    for label in ("protoclj", "bb"):
        res[label] = [parse(out / f"{n}_{label}_r{r}.time") for r in range(1, runs + 1)]
        outs[label] = {(out / f"{n}_{label}_r{r}.out").read_text() for r in range(1, runs + 1)}
        rcs = {(out / f"{n}_{label}_r{r}.rc").read_text().strip() for r in range(1, runs + 1)}
        if rcs != {"0"}: ok = False; print(f"  {n} {label}: non-zero exit {rcs}")
    same = len(outs["protoclj"]) == 1 and outs["protoclj"] == outs["bb"]
    ok = ok and same
    pt = statistics.median(x[0] for x in res["protoclj"]); bt = statistics.median(x[0] for x in res["bb"])
    pm = statistics.median(x[1] for x in res["protoclj"]) / 1024; bm = statistics.median(x[1] for x in res["bb"]) / 1024
    ratio = pt / bt if bt > 0 else float("inf")
    first = next(iter(outs["protoclj"])).strip().splitlines()
    shown = (first[0][:60] if first else "(empty)")
    print(f"{n:10} {pt:11.2f} {bt:8.2f} {ratio:6.1f} {pm:12.0f} {bm:7.0f}  {'same' if same else 'DIFFERENT'}: {shown}")
for label in ("protoclj", "bb"):
    p = out / f"startup_perf_{label}.txt"
    if p.exists():
        ms = [float(l.split(",")[0]) for l in p.read_text().splitlines() if "task-clock" in l]
        if ms: print(f"start-up {label}: task-clock {statistics.median(ms):.1f} ms (median of {len(ms)} passes x 50 runs: {', '.join(f'{x:.1f}' for x in ms)})")
print("all outputs identical across runtimes and runs" if ok else "MISMATCH: see the .out files")
sys.exit(0 if ok else 1)
PY
